fields.InputDefinition:
{
  "goal": "Open the 'Events' entity grid — type 'Events' in the LEFT sidebar 'Search entities...' box and click the exact 'Events' node (or navigate directly to http://localhost:4200/app/data-explorer/Data?entity=Events). Then walk these sections IN ORDER, and as you arrive at each set \"checkpointReached\" to the exact checkpoint name shown: (1) edit-persists — click a row, click 'Open Full Record', change the 'Location' text field to 'Persisted Edit 206', click 'Save Changes' in the top banner and wait for the save to confirm, then navigate back to the grid (or reload) and reopen the SAME record; verify 'Location' still shows 'Persisted Edit 206'; (2) edit-dropdown — on an Event full record find a dropdown/picklist field (e.g. 'Event Type'), open it and select a DIFFERENT option, then click the 'Save Changes' banner and confirm the save succeeds with the field showing the new option; (3) edit-date — find a date field (e.g. 'Start Date'), change it to a different date via the picker or by typing, click 'Save Changes' and confirm the save succeeds with no error; (4) record-history — in the record toolbar (row of icons at the TOP-LEFT above the Details card) click the History control (CLOCK icon, tooltip 'N version(s) tracked') and verify the 'Record Changes History' panel opens listing change entries (action + user + time) or a clear empty state. Keep going until every section has been visited. Pages can take 10-30s to load in this resource-constrained environment — wait for content rather than navigating away.",
  "startUrl": "http://localhost:4200/app/data-explorer/Data?entity=Events",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 65,
  "checkpoints": [
    {
      "name": "edit-persists",
      "instruction": "edit Location, save, reopen, confirm persisted",
      "assertions": [
        {
          "kind": "url",
          "urlPattern": "/app/data-explorer/Data"
        }
      ],
      "visualCriteria": [
        "After editing an Event's Location to 'Persisted Edit 206', saving, and reopening the same record, the saved value 'Persisted Edit 206' is still shown — the edit persisted"
      ]
    },
    {
      "name": "edit-dropdown",
      "instruction": "change a dropdown field and save",
      "visualCriteria": [
        "A dropdown/picklist field on an Event record was changed to a different option and saved successfully — the field shows the newly selected option with no error"
      ]
    },
    {
      "name": "edit-date",
      "instruction": "change a date field and save",
      "visualCriteria": [
        "A date field on an Event record was changed (via the date picker or typing) and 'Save Changes' succeeded with no error"
      ]
    },
    {
      "name": "record-history",
      "instruction": "open Record Changes History panel",
      "visualCriteria": [
        "The 'Record Changes History' panel is open, listing the record's change entries (action + user + time) or showing a clear empty state"
      ]
    }
  ]
}
